import{_ as r,C as i,o as t,c as n,a2 as a,b as d,w as s,a as l,E as c,a3 as p}from"./chunks/framework.CZqXuAiL.js";const C=JSON.parse('{"title":"GameFilter XDP","description":"Per-game, protocol-validating XDP (eBPF) firewall filter in Rust — only packets that provably speak the protocol assigned to each port reach your game servers.","frontmatter":{"title":"GameFilter XDP","description":"Per-game, protocol-validating XDP (eBPF) firewall filter in Rust — only packets that provably speak the protocol assigned to each port reach your game servers."},"headers":[],"relativePath":"gamefilter-xdp/index.md","filePath":"gamefilter-xdp/index.md","lastUpdated":1787907121000}'),h={name:"gamefilter-xdp/index.md"};function g(m,e,u,f,b,P){const o=i("Mermaid");return t(),n("div",null,[e[1]||(e[1]=a(`<h1 id="gamefilter-xdp" tabindex="-1">GameFilter XDP <a class="header-anchor" href="#gamefilter-xdp" aria-label="Permalink to &quot;GameFilter XDP&quot;">​</a></h1><p>Per-game, protocol-validating XDP filter — all Rust (aya-ebpf kernel program, aya userspace).</p><p>GameFilter XDP sits on the <strong>private NIC</strong> or <strong>VM bridge (<code>vmbr0</code> / <code>br0</code>)</strong> between your edge firewall (such as <a href="/pingless-studios-docs/openshield-xdp/">OpenShield-XDP</a>) and your game servers / guest VPSes. Every port a game listens on gets a filter; a packet only reaches the server if it <strong>provably speaks that game&#39;s protocol</strong>. Sources that pass validation once are admitted for a sliding TTL, so real players never notice the filter — and random flood garbage aimed at a game port dies in the NIC driver.</p><p>There are <strong>no pps knobs</strong>. Instead of guessing how many packets per second a &quot;legit&quot; client sends, GameFilter checks what the packet <em>is</em>: magic bytes at exact offsets, frame-length consistency, payload size bounds. A 10M pps UDP flood of random payloads to your Minecraft port is simply not RakNet — it is dropped on the first packet, and repeated failures temp-ban the source.</p><h2 id="topologies-modes" tabindex="-1">Topologies &amp; Modes <a class="header-anchor" href="#topologies-modes" aria-label="Permalink to &quot;Topologies &amp; Modes&quot;">​</a></h2><p>GameFilter supports two operating modes:</p><ul><li><strong><code>mode: dedicated</code> (Multi-Tenant / Proxmox / Dedicated Server):</strong> ONLY destination IPs enrolled under <code>tenants:</code> (or via the REST API) are inspected. All other destination IPs on the bridge bypass filtering instantly with <code>XDP_PASS</code> (100% transparent and safe for web, DB, and general guest VPSes).</li><li><strong><code>mode: vps</code> (Single Server / Standalone):</strong> Inspects all traffic arriving on the interface regardless of destination IP.</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Internet ──► Physical NIC (eno1) ──► OpenShield-XDP (Volumetric Anti-DDoS)</span></span>
<span class="line"><span>                    │ (Clean Traffic)</span></span>
<span class="line"><span>                    ▼</span></span>
<span class="line"><span>             VM Bridge (vmbr0) ──► GameFilter-XDP (Per-Game Protocol Validation)</span></span>
<span class="line"><span>                    │</span></span>
<span class="line"><span>       ┌────────────┴────────────┬────────────────────────┐</span></span>
<span class="line"><span>       ▼                         ▼                        ▼</span></span>
<span class="line"><span>Guest VPS A (Minecraft)   Guest VPS B (FiveM)     Guest VPS C (Web/DB)</span></span>
<span class="line"><span>[Enrolled: mc_java]       [Enrolled: fivem]       [Un-enrolled: 100% Bypassed]</span></span></code></pre></div><h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h2>`,9)),(t(),d(p,null,{default:s(()=>[c(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20P%5B%22Packet%20arrives%3Cbr%2F%3E(vmbr0%20%2F%20private%20NIC%2C%20XDP%20hook)%22%5D%20--%3E%20WL%7B%22Source%20in%3Cbr%2F%3EWHITELIST%3F%22%7D%0A%20%20%20%20WL%20--%3E%7C%22yes%22%7C%20PASS1%5B%22XDP_PASS%3Cbr%2F%3E(full%20bypass)%22%5D%0A%20%20%20%20WL%20--%3E%7C%22no%22%7C%20BL%7B%22Source%20in%3Cbr%2F%3EBLACKLIST%3F%22%7D%0A%20%20%20%20BL%20--%3E%7C%22permanent%20or%20unexpired%22%7C%20DROP1%5B%22XDP_DROP%22%5D%0A%20%20%20%20BL%20--%3E%7C%22no%20%2F%20expired%22%7C%20MODE%7B%22mode%3A%20dedicated%3F%22%7D%0A%20%20%20%20MODE%20--%3E%7C%22yes%22%7C%20TENANT%7B%22Destination%20IP%3Cbr%2F%3Ein%20TENANTS_MAP%3F%22%7D%0A%20%20%20%20TENANT%20--%3E%7C%22no%20(un-enrolled%20VPS)%22%7C%20BYPASS%5B%22XDP_PASS%3Cbr%2F%3E(instant%20safe%20bypass)%22%5D%0A%20%20%20%20TENANT%20--%3E%7C%22yes%22%7C%20OWN%7B%22Destination%20port%3Cbr%2F%3Eowned%20by%20a%20filter%3F%22%7D%0A%20%20%20%20MODE%20--%3E%7C%22no%20(vps%20mode)%22%7C%20OWN%0A%20%20%20%20OWN%20--%3E%7C%22no%22%7C%20DEF%7B%22default_action%22%7D%0A%20%20%20%20DEF%20--%3E%7C%22drop%22%7C%20DROP2%5B%22XDP_DROP%22%5D%0A%20%20%20%20DEF%20--%3E%7C%22pass%22%7C%20PASS2%5B%22XDP_PASS%22%5D%0A%20%20%20%20OWN%20--%3E%7C%22yes%22%7C%20ADM%7B%22Source%20admitted%3Cbr%2F%3Efor%20(src%2C%20dst%2C%20rule)%3F%3Cbr%2F%3E(sliding%20TTL)%22%7D%0A%20%20%20%20ADM%20--%3E%7C%22yes%22%7C%20PASS3%5B%22XDP_PASS%3Cbr%2F%3ETTL%20refreshed%22%5D%0A%20%20%20%20ADM%20--%3E%7C%22no%22%7C%20VAL%5B%22Protocol%20validator%3Cbr%2F%3Emagic%20bytes%20%C2%B7%20framing%20%C2%B7%20size%20bounds%22%5D%0A%20%20%20%20VAL%20--%3E%7C%22valid%22%7C%20ADMIT%5B%22XDP_PASS%20%2B%20admit%20source%3Cbr%2F%3Efor%20admission_ttl_sec%22%5D%0A%20%20%20%20VAL%20--%3E%7C%22invalid%22%7C%20FAIL%5B%22XDP_DROP%3Cbr%2F%3Efailure%20counted%20(60s%20window)%22%5D%0A%20%20%20%20FAIL%20--%3E%20BANQ%7B%22failures%20%3E%3D%3Cbr%2F%3Emax_failures%3F%22%7D%0A%20%20%20%20BANQ%20--%3E%7C%22yes%22%7C%20BAN%5B%22Temp-ban%20source%3Cbr%2F%3Efor%20ban_sec%22%5D%0A%20%20%20%20BANQ%20--%3E%7C%22no%22%7C%20DROP3%5B%22XDP_DROP%22%5D%0A"})]),fallback:s(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a(`<h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><ul><li><strong>Multi-Tenant / Proxmox ready</strong> — <code>mode: dedicated</code> inspects only enrolled tenant destination IPs; general VPSes bypass instantly with zero risk of breaking web or database workloads.</li><li><strong>Protocol proof, not rate guessing</strong> — validators check exact protocol structure (magic offsets, varint frame-length consistency), not just ports.</li><li><strong>7 built-in validators</strong> — <code>mc_java</code>, <code>raknet</code> (Bedrock/MCPE/Geyser), <code>fivem</code>, <code>source_engine</code> (CS2/CS:GO), <code>ssh_banner</code>, plus <code>tcp_generic</code> / <code>udp_generic</code> size-bounds fallbacks.</li><li><strong>Sliding admission TTL</strong> — a source that validates once is admitted per <code>(src_ip, dst_ip, rule)</code>; every further packet refreshes the window, so established players take the fast path.</li><li><strong>Failure → temp-ban escalation</strong> — <code>max_failures</code> invalid packets inside a 60-second window bans the source for <code>ban_sec</code>, enforced in kernel.</li><li><strong>Flexible port ownership</strong> — single ports (<code>&quot;25565&quot;</code>), lists, and ranges (<code>&quot;27015-27050&quot;</code>), up to 64 filters.</li><li><strong>Whitelist / blacklist</strong> — permanent or timed entries, managed live from the CLI or HTTP API without a reload.</li><li><strong>OpenShield-XDP list sync</strong> — mirrors OpenShield&#39;s whitelist/blacklist into the kernel maps (adds <em>and</em> removals), via its API, a JSON export file, or a direct read of its pinned ban maps.</li><li><strong>HTTP management API</strong> — token-authenticated, per-IP rate-limited; stats, metrics sampler, live tenant enrollment, filters, admissions, lists, config read/patch, hot reload. No TUI by design.</li><li><strong>Blip-free hot reload</strong> — delta-only port map updates, in-place rule writes, and admissions preserved for unchanged rules.</li></ul><h2 id="quick-install" tabindex="-1">Quick Install <a class="header-anchor" href="#quick-install" aria-label="Permalink to &quot;Quick Install&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Extract the release package, then:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./install.sh</span></span></code></pre></div><p>The installer auto-detects your environment (Bare Metal / Proxmox VE / KVM), suggests your bridge (e.g. <code>vmbr0</code>), prompts for deployment mode (<code>dedicated</code> vs <code>vps</code>), writes <code>/etc/gamefilter/gamefilter.yaml</code>, and starts the systemd services.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gamefilter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # view status, mode &amp; protected tenants</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gamefilter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> key</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # show API URL + key</span></span></code></pre></div><h2 id="built-in-validators" tabindex="-1">Built-in Validators <a class="header-anchor" href="#built-in-validators" aria-label="Permalink to &quot;Built-in Validators&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Validator</th><th>Protocols</th><th>Proof required on the first packet</th></tr></thead><tbody><tr><td><code>mc_java</code></td><td>Minecraft Java (TCP)</td><td>Full handshake frame: varint length (must match payload), packet id 0, protocol varint, address, port, next-state 1|2; legacy <code>FE 01</code> ping accepted</td></tr><tr><td><code>raknet</code></td><td>MC Bedrock / MCPE / Geyser (UDP)</td><td>RakNet magic <code>00ffff00…12345678</code> at the exact offset for ping (<code>0x01</code>) / open-connection-request (<code>0x05</code>, <code>0x07</code>)</td></tr><tr><td><code>fivem</code></td><td>FiveM (UDP)</td><td><code>0xFFFFFFFF</code> + <code>getinfo</code>/<code>getstatus</code>/<code>connect</code>, or an ENet CONNECT command (low nibble 2, ≥52 bytes)</td></tr><tr><td><code>source_engine</code></td><td>CS2 / CS:GO / Source (UDP)</td><td><code>0xFFFFFFFF</code> + A2S type byte; <code>T</code> additionally requires <code>Source Engine Query\\0</code></td></tr><tr><td><code>ssh_banner</code></td><td>SSH / SFTP (TCP)</td><td><code>SSH-</code> banner, ≤255 bytes (RFC 4253)</td></tr><tr><td><code>tcp_generic</code></td><td>any TCP</td><td>Size bounds + NULL/Xmas/FIN-scan flag rejection</td></tr><tr><td><code>udp_generic</code></td><td>any UDP</td><td>Size bounds only</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">TCP handshake packets are not admissions</p><p>SYN/ACK packets carry no payload and pass unvalidated — but they never admit a source. Admission only comes from a <strong>data packet</strong> that passes the protocol validator, so a spoofed handshake gets an attacker nothing.</p></div><h2 id="vs-generic-rate-limit-firewalls" tabindex="-1">vs. Generic Rate-Limit Firewalls <a class="header-anchor" href="#vs-generic-rate-limit-firewalls" aria-label="Permalink to &quot;vs. Generic Rate-Limit Firewalls&quot;">​</a></h2><p>GameFilter is a complement to rate-limiting firewalls like <a href="/pingless-studios-docs/openshield-xdp/">OpenShield-XDP</a>, not a replacement — run OpenShield on the public edge and GameFilter on the private NIC or bridge in front of the game servers.</p><table tabindex="0"><thead><tr><th></th><th>GameFilter XDP</th><th>Generic rate-limit firewall</th></tr></thead><tbody><tr><td>Decision basis</td><td>Protocol validity (magic bytes, framing, size bounds)</td><td>Packets/bytes per second per source</td></tr><tr><td>Multi-tenant safety</td><td>Dedicated mode bypasses non-game VPS IPs instantly</td><td>Inspects/drops all traffic on port across host</td></tr><tr><td>Tuning</td><td>Per-game payload bounds from documented protocol structure</td><td>Thresholds guessed from traffic baselines</td></tr><tr><td>Random-payload flood to a game port</td><td>Dropped on the <strong>first</strong> packet (not valid protocol)</td><td>Dropped only after a rate threshold trips</td></tr><tr><td>Legit player experience</td><td>Validated once, then admitted (sliding TTL fast path)</td><td>Counted against rate budgets forever</td></tr><tr><td>Attacker with valid-looking low-rate traffic</td><td>Blocked unless packets are protocol-perfect</td><td>Invisible below the threshold</td></tr><tr><td>Where it runs</td><td>Private NIC or VM bridge (<code>vmbr0</code>)</td><td>Public edge (<code>eno1</code>)</td></tr><tr><td>Management</td><td>HTTP API + CLI, hot reload, OpenShield list sync</td><td>Varies</td></tr></tbody></table><p><a href="./getting-started/installation">Installation →</a> · <a href="./configuration/reference">Configuration Reference →</a> · <a href="./user-guide/api">HTTP API →</a> · <a href="./architecture/overview">Architecture →</a></p>`,13))])}const y=r(h,[["render",g]]);export{C as __pageData,y as default};
